<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class LanguageTuitionCharge extends Model { protected $guarded=[]; protected $casts=['due_date'=>'date','original_amount'=>'decimal:2','discount_percentage'=>'decimal:2','discount_amount'=>'decimal:2','payable_amount'=>'decimal:2','paid_amount'=>'decimal:2']; public function student(){return $this->belongsTo(LanguageStudent::class,'language_student_id')->withTrashed();} public function lead(){return $this->belongsTo(LanguageLead::class,'language_lead_id')->withTrashed();} public function course(){return $this->belongsTo(LanguageCourse::class,'language_course_id')->withTrashed();} public function languageClass(){return $this->belongsTo(LanguageClass::class,'language_class_id')->withTrashed();} public function discount(){return $this->belongsTo(LanguageDiscountPolicy::class,'language_discount_policy_id')->withTrashed();} public function payments(){return $this->hasMany(LanguageTuitionPayment::class);} }
